CREATE DATABASE IF NOT EXISTS DB_SUCIA;
USE DB_SUCIA;
CREATE TABLE transacciones_sucias (num_boleta VARCHAR(50), cliente_id VARCHAR(20), sku VARCHAR(50), codigo_canal VARCHAR(50), fecha_transaccion VARCHAR(50), codigo_sucursal VARCHAR(50), cantidad INT, monto_neto DECIMAL(12,2));

CREATE TABLE cliente_sucio (cliente_id VARCHAR(20), nombre VARCHAR(150), comuna VARCHAR(100), region VARCHAR(100), segmento VARCHAR(50));
